parameters.text:
=Analyze the following bug report and generate a structured engineering ticket.

Reporter Name:
{{ $json.reporter_name }}

Reporter Email:
{{ $json.reporter_email }}

Application:
{{ $json.application }}

Environment:
{{ $json.environment }}

Browser:
{{ $json.browser }}

Device:
{{ $json.device }}

Page URL:
{{ $json.page_url }}

Bug Title:
{{ $json.bug_title }}

Bug Description:
{{ $json.bug_description }}

Steps to Reproduce:
{{ $json.steps_to_reproduce }}

Expected Result:
{{ $json.expected_result }}

Actual Result:
{{ $json.actual_result }}

Attachment:
{{ $json.attachment }}

Return the response as structured JSON only.

parameters.jsCode:
const response = JSON.parse($json.output);

return [
  {
    json: response
  }
];

// Get current timestamp
const now = new Date();

// Format date as YYYYMMDD
const date =
  now.getFullYear().toString() +
  String(now.getMonth() + 1).padStart(2, "0") +
  String(now.getDate()).padStart(2, "0");

// Generate random 4-digit number
const random = Math.floor(1000 + Math.random() * 9000);

// Create Ticket ID
const ticketId = `BUG-${date}-${random}`;

// Return Master Ticket Object
return [
  {
    json: {
      // Preserve all existing fields
      ...$json,

      // Ticket Information
      ticket_id: ticketId,
      ticket_type: "Bug",
      status: "Open",
      report_status: "Submitted",

      // Timestamps
      created_at: now.toISOString(),
      updated_at: now.toISOString(),
      closed_at: null,

      // Assignment
      assigned_to: "Unassigned",

      // Metadata
      source: "Bug Report Form",
      version: "1.0",
      resolution: "",

      // AI Metadata
      ai_confidence: $json.confidence ?? null
    }
  }
];

